"""Yukon Payment Schedule parser (pdftotext -layout text of the PDF generated by the YHCIP Physician Resources app).
Line model: [marker] code(4-6 digits)  description  fee  [Anes or Proc Code]. Continuation lines (indented, no code, no fee)
extend the description. Page header (section title, column headings, Preamble notice) and "Page N of M" footer are skipped.
Printed markers kept as printed: 'T' and '*' before the code. Rows repeated at a page break (same code, fee, text) are kept once."""
import re, subprocess
CODE = re.compile(r'^(\s{0,14})(?:(T|\*)\s*)?(\d{4,6})\s{2,}(\S.*)$')
FEE = re.compile(r'^(.*?)\s{2,}(-?[\d,]*\d\.\d\d)(?:\s{2,}(\d+(?:\.\d)?(?:\+T)?))?\s*$')
ORPHAN = re.compile(r'\s{3,}\d[\d,]*\.\d\d(\s+\S+)?\s*$')
HEAD = re.compile(r'^\s*(YHCIP/\s+Anes|YWCHSB\s+or Proc|These fees cannot be correctly interpreted.*|Page \d+ of \d+)\s*$')

def text(pdf):
    return subprocess.run(['pdftotext', '-layout', pdf, '-'], capture_output=True, text=True).stdout

def extract(pdf, first=21):
    t = text(pdf); pages = t.split('\f'); rows = []; problems = []; seen = set()
    sec = sub = ''
    for pi, pg in enumerate(pages):
        if pi + 1 < first: continue
        ls = pg.split('\n'); cur = None; blank = 0
        tl = [l for l in ls if l.strip()]
        if not tl: continue
        sec = tl[0].strip()          # running section title
        for l in ls:
            if not l.strip(): blank += 1; continue
            if HEAD.match(l) or l.strip() == sec: continue
            m = CODE.match(l)
            if m:
                mk, code, rest = m.group(2), m.group(3), m.group(4)
                f = FEE.match(rest)
                desc, fee, an = (f.group(1), f.group(2), f.group(3)) if f else (rest, None, None)
                cur = {'c': code, 'd': re.sub(r'\s+', ' ', desc).strip(), 's': sec, 'h': sub, 'p': pi + 1, 'l': str(pi + 1)}
                if fee is not None: cur['f'] = float(fee.replace(',', ''))
                if an: cur['an'] = an
                if mk: cur['mk'] = mk
                rows.append(cur); blank = 0; continue
            if ORPHAN.search(l):
                problems.append((pi + 1, 'fee line without code', l.strip()[:90])); cur = None; continue
            ind = len(l) - len(l.lstrip())
            if ind <= 4 and not re.search(r'\s{2,}\S', l.strip()):   # left-aligned heading
                sub = re.sub(r'\s+', ' ', l.strip()); cur = None; continue
            if cur is not None and blank <= 2:
                cur['d'] = (cur['d'] + ' ' + re.sub(r'\s+', ' ', l.strip())).strip(); blank = 0
    out = []
    for r in rows:
        k = (r['c'], r.get('f'), r['s'], r['d'][:60])
        if k in seen: continue
        seen.add(k); out.append(r)
    return pages, out, problems

if __name__ == '__main__':
    import sys, json, collections
    pages, rows, probs = extract(sys.argv[1])
    print(len(rows), 'rows', len({r['c'] for r in rows}), 'codes', len(probs), 'problems')
    for p in probs: print('PROB', p)
    print(collections.Counter(r['s'] for r in rows))
    print(collections.Counter(r.get('mk') for r in rows), sum('f' not in r for r in rows), 'no fee')
    json.dump(rows, open('/tmp/yt/rows.json', 'w'), indent=0, ensure_ascii=False)
